namespace sv_d3e44dec8aac45eaa4324c55cee46737.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, "Scoped" means one instance per SignalR circuit,
/// so each user/tab gets independent state automatically.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public Theme Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@*
    Interactive island that lives in the static MainLayout header.
    Because it has @rendermode InteractiveServer, it can subscribe
    to the scoped ThemeService and re-render when theme changes.
*@
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@implements IDisposable
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Current: @ThemeService.Theme">
    @GetIcon()
</button>

@code {
    private void CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            _            => Theme.Light
        };
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        _            => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px; border-color: @ThemeService.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <button class="btn @(ThemeService.Theme == t ? "btn-primary" : "btn-outline-primary")"
                        style="@(ThemeService.Theme == t ? $"background-color:{ThemeService.AccentColor};border-color:{ThemeService.AccentColor}" : "")"
                        @onclick="() => ThemeService.Theme = t">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <input type="color" class="form-control form-control-color mb-2"
               value="@ThemeService.AccentColor"
               @onchange="OnColorChanged" />

        <small class="text-muted">@ThemeService.AccentColor</small>
    </div>
</div>

@code {
    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

